(function(){
const D=window.MPT_DATA;
const STAGES=D.stages;
let _state=null,_session={authenticated:false},_system={initialized:false,groupCount:0};
const deepClone=x=>JSON.parse(JSON.stringify(x));
const now=()=>new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});
const iso=()=>new Date().toISOString();
const baseState=()=>({
 project:'',className:'',groupCount:0,groupId:1,currentStage:1,stagePaused:false,aiOpen:true,
 projectType:'',projectHours:'',hintQuota:3,hintUsed:0,maxHintLevel:3,broadcast:'',
 roles:['建模者','质疑者','记录者','解释者'],members:['','','',''],roleRound:1,
 stageSubmitted:{1:false,2:false,3:false,4:false,5:false},stageTimes:{1:'进行中',2:'待进入',3:'待进入',4:'待进入',5:'待进入'},
 workspace:{problem:'',known:'',unknown:'',constraints:'',variables:'',relation:'',model:'',evidence:'',next:''},questionTree:['','','','',''],graphConfig:{a:'',b:'',c:'',min:'',max:'',note:''},checklist:{},
 versions:[],evidence:[],viewpoints:[],firstThoughts:{},helpHistory:[],debate:[],product:{audience:'',title:'',claim:'',limitations:'',rehearsal:'',reflection:''},
 teacherConfig:{mathTopic:'',standard:'',finalProduct:'',stages:'',knowledge:[],staticHints:['先标出已知、未知和约束。','把当前卡点拆成一个可检验的子问题。','选择一步计算、测量或反例进行核验。']},
 groups:[],queue:[],common:[],evaluations:{},
 audit:[],events:[],aiCalls:[]
});
function defaultState(){const s=baseState();s.groupCount=_system.groupCount||0;s.groups=Array.from({length:s.groupCount},(_,i)=>({id:i+1,stage:1,status:'准备中',help:0,maxHint:0,teacher:false,latest:'尚未保存',issue:'',progress:0}));return s}
async function api(path,options={}){const init={credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options};const res=await fetch(path,init);const type=res.headers.get('content-type')||'';const data=type.includes('application/json')?await res.json():null;if(!res.ok)throw new Error((data&&data.error)||`请求失败（${res.status}）`);return data}
function load(){return _state||defaultState()}
function save(s){_state=s;api('/api/state',{method:'PUT',keepalive:true,body:JSON.stringify({state:s})}).catch(e=>toast(`保存失败：${e.message}`))}
async function reset(){try{await api('/api/state/reset',{method:'POST',body:'{}'});location.reload()}catch(e){toast(e.message)}}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'})}finally{location.href='/?current'}}
function event(s,type,data='',group='',stage=s.currentStage){const actual=group||`G${String(s.groupId||1).padStart(2,'0')}`;s.events.push({ts:iso(),type,group:actual,stage,data});if(s.events.length>120)s.events=s.events.slice(-120);}
function audit(s,actor,action,detail){s.audit.unshift({time:now(),actor,action,detail});if(s.audit.length>80)s.audit=s.audit.slice(0,80)}
function toast(msg){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el)}el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2200)}
function esc(x){return String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function safeCalculate(source){const text=String(source).replace(/\s+/g,'');let at=0;const number=()=>{const start=at;while(/[0-9.]/.test(text[at]||''))at++;if(start===at)throw new Error('需要数字');const value=Number(text.slice(start,at));if(!Number.isFinite(value))throw new Error('数字无效');return value};const factor=()=>{if(text[at]==='('){at++;const value=expression();if(text[at]!==')')throw new Error('括号不匹配');at++;return value}if(text[at]==='-'){at++;return -factor()}return number()};const term=()=>{let value=factor();while(text[at]==='*'||text[at]==='/'){const op=text[at++],right=factor();if(op==='/'&&right===0)throw new Error('不能除以0');value=op==='*'?value*right:value/right}return value};const expression=()=>{let value=term();while(text[at]==='+'||text[at]==='-'){const op=text[at++],right=term();value=op==='+'?value+right:value-right}return value};const result=expression();if(at!==text.length||!Number.isFinite(result))throw new Error('表达式无效');return result}
function stage(n){return STAGES[n-1]}
function stageStrip(active){const s=load();return `<div class="stage-strip">${STAGES.map(x=>`<a class="stage-card ${s.stageSubmitted[x.n]?'done':''} ${active===x.n?'current':''}" href="stage${x.n}.html"><div class="stage-no">阶段 ${x.n}</div><div class="stage-name">${x.name}</div><div class="stage-state">${s.stageSubmitted[x.n]?'已完成':active===x.n?'当前':'待进入'}</div><div class="stage-output">${x.output}</div></a>`).join('')}</div>`}
function btn(label,cls='',id='',extra=''){return `<button class="btn ${cls}" ${id?`id="${id}"`:''} ${extra}>${label}</button>`}
function badge(t,cls=''){return `<span class="badge ${cls}">${t}</span>`}
function studentNav(active){const s=load();return `<aside class="sidebar"><div class="nav-label">课堂导航</div><nav class="nav"><a class="${active==='home'?'active':''}" href="dashboard.html">▸ 课堂首页</a>${STAGES.map(x=>`<a class="sub ${active===`s${x.n}`?'active':''}" href="stage${x.n}.html">${x.n} ${x.name}</a>`).join('')}<div class="sep"></div><a class="${active==='workspace'?'active':''}" href="workspace.html">▸ 共享工作区</a><a class="${active==='group'?'active':''}" href="group.html">▸ 小组协作与角色</a><a class="${active==='help'?'active':''}" href="help.html">▸ 提示与求助 <span class="count">${s.hintUsed}/${s.hintQuota}</span></a><a class="${active==='history'?'active':''}" href="history.html">▸ 过程与版本回看</a><div class="nav-label">系统说明</div><a class="${active==='gov'?'active':''}" href="governance.html">▸ 数据使用说明</a><a href="/?current">▸ 返回登录入口</a></nav></aside>`}
function teacherNav(active){const links=[['home','课堂总览','dashboard.html'],['project','项目与支架配置','project.html'],['template','项目模板','template.html'],['knowledge','项目知识库','knowledge.html'],['scaffold','提示与支架规则','scaffolds.html'],['stages','课堂阶段控制','stages.html'],['groups','小组态势','groups.html'],['detail','小组详情','group-detail.html'],['queue','教师升级队列','queue.html'],['common','共性问题','common.html'],['broadcast','广播与共性澄清','broadcast.html'],['eval','成果评价','evaluation.html'],['report','课后总结','report.html'],['export','课堂数据导出','export.html'],['gov','运行与数据治理','governance.html'],['audit','审计与模型调用','audit.html'],['access','账号与访问管理','access.html']];const s=load();return `<aside class="sidebar"><div class="nav-label">课堂导航</div><nav class="nav">${links.map(x=>`<a class="${active===x[0]?'active':''}" href="${x[2]}">▸ ${x[1]}${x[0]==='queue'?`<span class="count">${s.queue.filter(q=>!q.resolved).length}</span>`:''}</a>`).join('')}<div class="nav-label">系统</div><a href="/?current">▸ 返回登录入口</a></nav></aside>`}
function topbar(role){const s=load();const student=role==='student',className=s.className||'未填写班级名称';return `<header class="topbar"><div class="brand"><span class="logo">Σ</span><span>数学项目协作智能体</span></div><div class="top-actions"><span class="pill"><i class="status-dot ${s.aiOpen?'on':'off'}"></i>AI${s.aiOpen?'开放':'暂停'}</span><span class="pill">${student?`${className} · ${s.groupId}组 · 小组端`:`${className} · 教师总控端`}</span><button class="btn sm" data-logout>退出登录</button></div></header>`}
function shell(role,active,body){return `<div class="app">${topbar(role)}<div class="shell">${role==='student'?studentNav(active):teacherNav(active)}<main class="main">${body}<div class="footer-note">${role==='student'?'治理边界：不持续采集音视频，不自动识别学生情绪，不自动形成能力标签；数学核心判断和最终评价由学生与教师承担。':'教师保留AI开关、阶段推进、复杂冲突、高阶数学判断和最终评价权。所有自动摘要保留原记录入口。'}</div></main></div></div><div class="toast"></div>`}
function head(title,desc,actions='',eyebrow=''){return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function metric(k,v,s='',p=null){return `<div class="card metric"><div class="k">${k}</div><div class="v">${v}</div><div class="s">${s}</div>${p===null?'':`<div class="progress"><i style="width:${p}%"></i></div>`}</div>`}
function modal(title,html){const m=document.createElement('div');m.className='modal-mask';m.innerHTML=`<div class="modal"><div class="page-head"><div><h2>${title}</h2></div><button class="btn sm" data-close>关闭</button></div>${html}</div>`;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.dataset.close!==undefined)m.remove()})}
function setRoot(html){document.querySelector('#root').innerHTML=html}
function saveFields(selector,mapFn){document.querySelectorAll(selector).forEach(el=>mapFn(el))}
function renderStudentDashboard(){const s=load();if(!s.project){setRoot(shell('student','home',head('项目尚未配置','教师完成项目配置后，这里才会显示阶段、任务和课堂状态。','','学生小组端')+`<section class="card"><div class="empty"><h2>等待教师创建项目</h2><p>当前没有可参与的课堂项目。</p></div></section>`));return}const title=s.project?`${s.teacherConfig.mathTopic?esc(s.teacherConfig.mathTopic)+' · ':''}${esc(s.project)}`:'项目尚未配置',description=s.teacherConfig.standard||'请等待教师完成项目配置。';const pending=s.broadcast?`<div class="info mt12"><b>教师广播：</b>${esc(s.broadcast)}</div>`:'';setRoot(shell('student','home',head(title,description,`<a class="btn primary" href="help.html">需要提示</a><a class="btn" href="workspace.html">共享工作区</a>`,'学生小组端')+pending+stageStrip(s.currentStage)+`<div class="grid cols-4">${metric('当前阶段',`${s.currentStage}/5`,stage(s.currentStage).full)}${metric('课堂状态',s.stagePaused?'已暂停':'进行中','教师控制推进')}${metric('阶段产出',s.stageSubmitted[s.currentStage]?'已提交':'进行中',stage(s.currentStage).output)}${metric('提示额度',`${s.hintUsed}/${s.hintQuota}`,s.aiOpen?'AI可用 · 先思后助':'AI已由教师暂停')}</div><div class="grid cols-2 mt16"><section class="card"><h2>本阶段要完成什么</h2><div class="task-list"><div class="task"><b>① 明确变量与对象</b><small>说明哪些量可变、哪些量固定，并写清符号和单位。</small></div><div class="task"><b>② 建立数量关系</b><small>用式子、图表、图形或推理表示关键关系。</small></div><div class="task"><b>③ 检查现实约束</b><small>把题目与现实条件转化为数学限制和取值范围。</small></div><div class="task"><b>④ 设计验证方法</b><small>计算、图像、测量、证明或边界检查至少选择一种。</small></div></div><div class="toolbar"><a class="btn green" href="stage${s.currentStage}.html">进入阶段工作台</a><a class="btn" href="stage3-check.html">查看核验清单</a></div></section><section class="card"><h2>小组角色与数学责任</h2><table class="table"><thead><tr><th>成员</th><th>角色</th><th>本阶段数学责任</th></tr></thead><tbody>${s.members.map((m,i)=>`<tr><td>${esc(m||'未填写')}</td><td><b>${s.roles[i]}</b></td><td>${['提出模型或解法草稿并解释对象','检查条件、假设和证据','记录证据与版本变化','向组员复述推理与结论'][i]}</td></tr>`).join('')}</tbody></table><div class="note mt12">阶段切换时轮换角色。系统只提醒任务责任，不按发言次数评价个人。</div></section></div>`))}
const stageTasks={1:['确认项目目标与成果对象','确认项目材料与设备状态','完成角色分配与第一轮数学责任','了解AI边界、提示额度和阶段规则'],2:['每人先写一句任务理解','小组合并任务复述','列出已知、未知、变量候选和约束','建立问题树并提交阶段2产出'],3:['定义变量与实际范围','写出数量关系','形成模型V1并说明假设','设计验证方法和待核验清单'],4:['执行计算/测量/推理','把证据写入证据包','用观点比较卡处理分歧','形成模型修订与理由'],5:['整理问题—模型—证据—结论链','完成成果页与组内预演','回应质疑并记录互评','回看提示、版本和协作过程']};
const stageLinks={1:[['材料与规则','stage1-materials.html'],['角色确认','stage1-roles.html']],2:[['任务理解表','stage2-understanding.html'],['问题树','stage2-question-tree.html']],3:[['模型编辑','stage3-model.html'],['函数图像核验','stage3-graph.html'],['方案比较','stage3-compare.html'],['核验清单','stage3-check.html']],4:[['证据包','stage4-evidence.html'],['观点协商','stage4-discussion.html'],['版本历史','stage4-versions.html'],['数学工具','stage4-tools.html']],5:[['成果整理','stage5-product.html'],['展示预演','stage5-rehearsal.html'],['反思评价','stage5-reflection.html']]};
function renderStage(n){const s=load(),st=stage(n),submitted=s.stageSubmitted[n];const special={1:'AI默认静默。项目资料、提示规则和课堂边界由教师预设。',2:'先完成个人理解和小组复述，再使用任务澄清提示。系统不直接生成完整模型。',3:'L1目标定位→L2结构提示→L3局部支架。核心模型与最优判断保留给小组。',4:'工具支持机械计算和证据整理；复杂冲突、高阶数学判断和连续失败转教师。',5:'系统整理已有过程、核验表达完整性；最终成果、答辩和评分由学生与教师完成。'}[n];setRoot(shell('student','s'+n,head(`${st.full}`,`本阶段产出：${st.output}`,`<a class="btn" href="workspace.html">共享工作区</a>${n>1?'<a class="btn primary" href="help.html">主动求助</a>':''}` ,`阶段 ${n}`)+stageStrip(n)+`<div class="grid cols-2"><section class="card"><h2>阶段任务与提交</h2><div class="task-list">${stageTasks[n].map((x,i)=>`<div class="task flex"><div><b>${i+1}. ${x}</b><small>${n===3&&i===2?'至少保存一个可回看的模型版本。':n===4&&i===2?'围绕证据和数学对象表达异议。':'完成后在阶段工作区保存。'}</small></div>${badge(submitted?'已记录':'待完成',submitted?'ok':'blue')}</div>`).join('')}</div><div class="toolbar">${btn(submitted?'已提交阶段产出':'提交本阶段产出',submitted?'ghost':'green','submitStage',submitted?'disabled':'')} ${n<5?`<span class="muted small">教师决定是否推进到阶段${n+1}</span>`:''}</div></section><section class="card"><h2>本阶段工具</h2><div class="task-list">${stageLinks[n].map(x=>`<a class="task" href="${x[1]}"><b>▸ ${x[0]}</b><small>进入二级/三级工作页面</small></a>`).join('')}</div><div class="info mt12">${special}</div></section></div>`));const b=document.querySelector('#submitStage');if(b)b.onclick=()=>{const x=load();x.stageSubmitted[n]=true;event(x,'stage_submit',st.output);save(x);toast(`阶段${n}产出已提交，教师端可查看`);setTimeout(()=>renderStage(n),300)}}
function renderStage1Materials(){const s=load();setRoot(shell('student','s1',head('项目材料与课堂规则','确认项目的数学目标、成果对象、资料来源和使用边界。','<a class="btn" href="stage1.html">返回阶段1</a>','阶段1 · 二级页面')+`<div class="grid cols-2"><section class="card"><h2>项目简报</h2><div class="mini-stat"><span>项目名称</span><b>${esc(s.project)}</b></div><div class="mini-stat"><span>数学主题</span><b>${esc(s.teacherConfig.mathTopic)}</b></div><div class="mini-stat"><span>成果形式</span><b>${esc(s.teacherConfig.finalProduct)}</b></div><div class="info mt12"><b>数学目标</b><br>${esc(s.teacherConfig.standard)}</div></section><section class="card"><h2>教师审核材料</h2><div class="task-list">${s.teacherConfig.knowledge.length?s.teacherConfig.knowledge.map(x=>`<div class="task flex"><div><b>${esc(x)}</b><small>项目级知识库 · 教师审核</small></div>${badge('已同步','ok')}</div>`).join(''):'<div class="empty">教师尚未发布项目材料</div>'}</div><h3 class="mt16">课堂规则</h3><div class="locked-rule"><span>AI默认静默，学生主动求助才进入</span>${badge('启用','ok')}</div><div class="locked-rule mt8"><span>首次响应不提供完整答案</span>${badge('锁定','blue')}</div><div class="locked-rule mt8"><span>复杂冲突与最终评价由教师处理</span>${badge('锁定','blue')}</div></section></div>`))}
function renderStage1Roles(){const s=load();setRoot(shell('student','s1',head('成员与角色确认','填写本组成员称呼并确认数学责任，阶段转换时可轮换。','<a class="btn" href="stage1.html">返回阶段1</a>','阶段1 · 二级页面')+`<section class="card"><table class="table"><thead><tr><th>成员称呼</th><th>当前角色</th><th>责任说明</th></tr></thead><tbody>${s.members.map((m,i)=>`<tr><td><div class="field"><input data-member="${i}" value="${esc(m)}" placeholder="由小组填写"></div></td><td>${s.roles[i]}</td><td>${['提出变量和模型草稿','检查假设、范围和证据','维护共同问题空间与版本','负责组内复述和成果表达'][i]}</td></tr>`).join('')}</tbody></table><div class="toolbar">${btn('保存成员','green','saveMembers')}${btn('轮换角色','primary','rotateRole')}<span class="muted small">成员数据仅保存在本组空间，不用于能力评价。</span></div></section>`));document.querySelector('#saveMembers').onclick=()=>{const x=load();x.members=Array.from(document.querySelectorAll('[data-member]')).map(el=>el.value.trim());save(x);toast('本组成员已保存')};document.querySelector('#rotateRole').onclick=()=>{const x=load();x.roles.unshift(x.roles.pop());x.roleRound+=1;event(x,'role_rotate',`轮次${x.roleRound}`);save(x);toast('角色已轮换');setTimeout(renderStage1Roles,250)}}
function renderStage2Understanding(){const s=load();setRoot(shell('student','s2',head('任务理解表','先形成个人理解，再汇总为小组的任务复述、信息和约束。','<a class="btn" href="stage2.html">返回阶段2</a>','阶段2 · 二级页面')+`<div class="grid cols-2"><section class="card"><h2>个人先想卡</h2>${s.members.map((m,i)=>`<div class="field mt8"><label>${m||'成员'+(i+1)} · 先写一句</label><input data-thought="${i}" value="${esc(s.firstThoughts[i]||'')}"></div>`).join('')}<div class="toolbar">${btn('保存个人先想','primary','saveThought')}</div><div class="note">这里只保存每人的任务思路，不公开排名、不计算“积极程度”。</div></section><section class="card"><h2>小组任务复述</h2><div class="field"><label>我们要解决的问题</label><textarea data-w="problem">${esc(s.workspace.problem)}</textarea></div><div class="field mt8"><label>已知信息</label><textarea data-w="known">${esc(s.workspace.known)}</textarea></div><div class="field mt8"><label>未知/需要确定</label><textarea data-w="unknown">${esc(s.workspace.unknown)}</textarea></div><div class="field mt8"><label>现实约束</label><textarea data-w="constraints">${esc(s.workspace.constraints)}</textarea></div><div class="toolbar">${btn('保存小组理解','green','saveUnderstanding')}<a class="btn" href="help.html">任务澄清提示</a></div></section></div>`));document.querySelector('#saveThought').onclick=()=>{const x=load();document.querySelectorAll('[data-thought]').forEach(el=>x.firstThoughts[el.dataset.thought]=el.value.trim());event(x,'first_think_save',s.members.length+'人个人先想');save(x);toast('个人先想已保存')};document.querySelector('#saveUnderstanding').onclick=()=>{const x=load();document.querySelectorAll('[data-w]').forEach(el=>x.workspace[el.dataset.w]=el.value);event(x,'understanding_save','任务复述与信息约束');save(x);toast('小组任务理解已保存')}}
function renderQuestionTree(){const s=load(),labels=['核心问题','子问题1','子问题2','子问题3','子问题4'];setRoot(shell('student','s2',head('问题树','把开放情境拆成可讨论、可验证的数学子问题。','<a class="btn" href="stage2.html">返回阶段2</a>','阶段2 · 三级页面')+`<section class="card"><div class="task-list">${labels.map((label,i)=>`<div class="field"><label>${label}</label><textarea data-question="${i}" placeholder="${i===0?'写出项目需要解决的核心问题':'写出一个可验证的数学子问题'}">${esc((s.questionTree||[])[i]||'')}</textarea></div>`).join('')}</div><div class="toolbar">${btn('保存问题树','primary','saveTree')}<a class="btn" href="stage3.html">进入方案与建模</a></div></section>`));document.querySelector('#saveTree').onclick=()=>{const x=load();x.questionTree=Array.from(document.querySelectorAll('[data-question]')).map(el=>el.value.trim());event(x,'question_tree_save',`${x.questionTree.filter(Boolean).length}节点`);save(x);toast('问题树已保存')}}
function renderWorkspace(){const s=load(),w=s.workspace;const fields=[['共同问题','problem'],['已知信息','known'],['现实约束','constraints'],['变量','variables'],['数量关系','relation'],['当前模型','model'],['证据/待核验','evidence'],['下一步','next']];setRoot(shell('student','workspace',head('共享工作区','一组一平板共同维护。这里保存讨论对象、数学模型、证据、待核验点和下一步。',`<button class="btn green" id="newVersion">保存新版本</button><a class="btn primary" href="help.html">需要提示</a>`,'共同问题空间')+`<div class="tabs"><a class="tab active">共同问题</a><a class="tab" href="stage3-model.html">模型编辑</a><a class="tab" href="stage3-compare.html">方案比较</a><a class="tab" href="stage4-evidence.html">证据包</a><a class="tab" href="stage4-versions.html">版本历史</a></div><div class="workspace"><section class="card"><h2>共同问题空间</h2>${fields.map(f=>`<div class="field mt8"><label>${f[0]}</label><textarea data-work="${f[1]}">${esc(w[f[1]])}</textarea></div>`).join('')}<div class="toolbar">${btn('保存工作区','primary','saveWorkspace')}</div></section><aside class="card"><h2>版本与课堂状态</h2><div class="mini-stat"><span>当前阶段</span><b>${stage(s.currentStage).full}</b></div><div class="mini-stat"><span>AI状态</span><b>${s.aiOpen?'开放':'暂停'}</b></div><div class="mini-stat"><span>提示额度</span><b>${s.hintUsed}/${s.hintQuota}</b></div><div class="divider"></div><div class="timeline">${s.versions.slice().reverse().map(v=>`<div class="tl"><div class="tl-time">${v.time}</div><div class="tl-body"><b>${v.v}</b><br>${esc(v.note)}</div></div>`).join('')}</div><div class="note mt12">版本用于解释“我们为什么修改”，不作为成员能力评分。</div></aside></div>`));document.querySelector('#saveWorkspace').onclick=()=>{const x=load();document.querySelectorAll('[data-work]').forEach(el=>x.workspace[el.dataset.work]=el.value);event(x,'workspace_save','共享工作区');save(x);toast('共享工作区已保存')};document.querySelector('#newVersion').onclick=()=>{const x=load();const v='V'+(x.versions.length+1);x.versions.push({v,time:now(),note:'根据新证据修订模型与约束',model:x.workspace.model});event(x,'version_save',v);save(x);toast(`${v} 已保存`);setTimeout(renderWorkspace,250)}}
function renderStage3Model(){const s=load();setRoot(shell('student','s3',head('变量、关系与模型编辑','把数学化过程拆成可核对的结构，核心模型由小组形成。','<a class="btn" href="stage3.html">返回阶段3</a>','阶段3 · 三级页面')+`<div class="tabs"><a class="tab active">模型编辑</a><a class="tab" href="stage3-graph.html">函数图像</a><a class="tab" href="stage3-compare.html">方案比较</a><a class="tab" href="stage3-check.html">核验清单</a></div><div class="grid cols-2"><section class="card"><div class="field"><label>变量定义</label><textarea id="m-var">${esc(s.workspace.variables)}</textarea></div><div class="field mt8"><label>数量关系</label><textarea id="m-rel">${esc(s.workspace.relation)}</textarea></div><div class="field mt8"><label>模型/函数/证明思路</label><textarea id="m-model">${esc(s.workspace.model)}</textarea></div><div class="field mt8"><label>实际取值范围与限制</label><textarea id="m-range">${esc(s.workspace.constraints)}</textarea></div><div class="toolbar">${btn('保存模型草稿','primary','saveModel')}<a class="btn" href="help.html">分级提示</a></div></section><section class="card"><h2>建模检查</h2><div class="task-list"><div class="task"><b>变量是否有现实含义和单位</b></div><div class="task"><b>数量关系是否来自题目或测量证据</b></div><div class="task"><b>模型是否对应项目目标</b></div><div class="task"><b>取值范围是否包含全部现实限制</b></div></div><div class="info mt12">AI只会指出检查维度。最终模型和数学判断需要小组给出并解释。</div></section></div>`));document.querySelector('#saveModel').onclick=()=>{const x=load();x.workspace.variables=document.querySelector('#m-var').value;x.workspace.relation=document.querySelector('#m-rel').value;x.workspace.model=document.querySelector('#m-model').value;x.workspace.constraints=document.querySelector('#m-range').value;event(x,'model_save','模型草稿');save(x);toast('模型草稿已保存')}}
function drawGraph(){const c=document.querySelector('#graph');if(!c)return;const g=load().graphConfig||{},a=Number(g.a)||0,b=Number(g.b)||0,d=Number(g.c)||0,min=Number(g.min),max=Number(g.max);if(!Number.isFinite(min)||!Number.isFinite(max)||min>=max)return;const rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1,W=rect.width,H=320,pad=42;c.width=W*dpr;c.height=H*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const f=x=>a*x*x+b*x+d,values=Array.from({length:201},(_,i)=>f(min+(max-min)*i/200)),low=Math.min(...values,0),high=Math.max(...values,0),span=high-low||1,xp=x=>pad+(W-pad-14)*(x-min)/(max-min),yp=y=>H-pad-(H-pad-14)*(y-low)/span;ctx.clearRect(0,0,W,H);ctx.strokeStyle='#cdd9e3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,yp(0));ctx.lineTo(W-12,yp(0));if(min<=0&&max>=0){ctx.moveTo(xp(0),12);ctx.lineTo(xp(0),H-pad)}ctx.stroke();ctx.fillStyle='#64778b';ctx.font='12px Microsoft YaHei';ctx.fillText('y',12,18);ctx.fillText('x',W-20,yp(0)+18);ctx.strokeStyle='#176d96';ctx.lineWidth=2.5;ctx.beginPath();values.forEach((y,i)=>{const x=min+(max-min)*i/200;i?ctx.lineTo(xp(x),yp(y)):ctx.moveTo(xp(x),yp(y))});ctx.stroke();for(let i=0;i<=4;i++){const x=min+(max-min)*i/4;ctx.fillStyle='#7a8ca0';ctx.fillText(Number(x.toFixed(2)),xp(x)-8,H-12)}}
function renderStage3Graph(){const s=load(),g=s.graphConfig||{};setRoot(shell('student','s3',head('函数图像与边界核验','输入小组已经建立的二次函数系数，用图像核验趋势、零点和可行范围。','<a class="btn" href="stage3.html">返回阶段3</a>','阶段3 · 三级页面')+`<div class="grid cols-2"><section class="card"><h2>函数图像</h2><div class="canvas-wrap"><canvas id="graph" class="graph-canvas"></canvas></div><div class="note mt12">图像只作核验，不替代函数建立、范围判断或最终解释。</div></section><section class="card"><h2>函数与核验记录</h2><div class="form-grid"><div class="field"><label>a</label><input id="graphA" type="number" step="any" value="${g.a??''}"></div><div class="field"><label>b</label><input id="graphB" type="number" step="any" value="${g.b??''}"></div><div class="field"><label>c</label><input id="graphC" type="number" step="any" value="${g.c??''}"></div><div class="field"><label>x最小值</label><input id="graphMin" type="number" step="any" value="${g.min??''}"></div><div class="field"><label>x最大值</label><input id="graphMax" type="number" step="any" value="${g.max??''}"></div></div><div class="field mt8"><label>本组核验判断</label><textarea id="graphJudge">${esc(g.note||'')}</textarea></div><div class="toolbar">${btn('更新图像并保存','primary','saveGraphJudge')}</div></section></div>`));requestAnimationFrame(drawGraph);window.addEventListener('resize',drawGraph,{once:true});document.querySelector('#saveGraphJudge').onclick=()=>{const raw=['graphA','graphB','graphC','graphMin','graphMax'].map(id=>document.querySelector('#'+id).value.trim());if(raw.some(v=>v==='')){toast('请完整填写系数和x范围');return}const nums=raw.map(Number),x=load();x.graphConfig={a:nums[0],b:nums[1],c:nums[2],min:nums[3],max:nums[4],note:document.querySelector('#graphJudge').value.trim()};if(!nums.every(Number.isFinite)||x.graphConfig.min>=x.graphConfig.max){toast('请填写有效的系数和x范围');return}event(x,'graph_check',x.graphConfig.note);save(x);drawGraph();toast('函数图像与核验判断已保存')}}
function renderCompare(){const s=load();if(!s.viewpoints.length)s.viewpoints=[{who:'方案A',claim:'',basis:'',risk:''},{who:'方案B',claim:'',basis:'',risk:''}];setRoot(shell('student','s3',head('方案证据比较卡','把分歧写成“方案—依据—风险—待核验”，支持围绕数学证据协商。','<a class="btn" href="stage3.html">返回阶段3</a>','阶段3/4 · 三级页面')+`<div class="compare-grid">${s.viewpoints.slice(0,2).map((v,i)=>`<section class="card"><div class="eyebrow">${v.who}</div><div class="field"><label>方案</label><textarea data-v="${i}" data-k="claim">${esc(v.claim)}</textarea></div><div class="field mt8"><label>依据</label><textarea data-v="${i}" data-k="basis">${esc(v.basis)}</textarea></div><div class="field mt8"><label>风险/局限与待核验点</label><textarea data-v="${i}" data-k="risk">${esc(v.risk)}</textarea></div></section>`).join('')}</div><div class="card mt16"><h2>比较要求</h2><div class="task-list"><div class="task"><b>目标一致</b><small>两个方案都在回答同一个核心问题。</small></div><div class="task"><b>依据可查</b><small>每个判断能够回到数据、条件、定理或计算。</small></div><div class="task"><b>限制明确</b><small>写出适用范围、误差和仍需验证的部分。</small></div></div><div class="toolbar">${btn('保存方案比较','primary','saveCompare')}<a class="btn" href="stage4-discussion.html">进入观点协商</a></div></div>`));document.querySelector('#saveCompare').onclick=()=>{const x=load();document.querySelectorAll('[data-v]').forEach(el=>x.viewpoints[+el.dataset.v][el.dataset.k]=el.value);event(x,'compare_save','方案A/B');save(x);toast('方案比较已保存')}}
function renderCheck(){const s=load(),items=['变量、符号和单位定义清楚','数量关系有题目条件或证据支持','计算、测量或推理过程可以复核','取值范围同时满足数学与现实限制','结果已用另一种方法或边界情况核验','结论回应项目目标并说明局限'];setRoot(shell('student','s3',head('数学核验清单','把范围、单位、条件和合理性检查从最后补救变成过程检查。','<a class="btn" href="stage3.html">返回阶段3</a>','阶段3 · 三级页面')+`<section class="card"><div class="task-list">${items.map((x,i)=>`<label class="task flex"><div><b>${i+1}. ${x}</b></div><input data-check="${i}" type="checkbox" ${s.checklist?.[i]?'checked':''}></label>`).join('')}</div><div class="toolbar">${btn('保存检查结果','primary','saveCheck')}</div><div class="info">该清单只帮助发现遗漏，不自动判断最终模型正确。</div></section>`));document.querySelector('#saveCheck').onclick=()=>{const x=load();x.checklist={};document.querySelectorAll('[data-check]').forEach(el=>x.checklist[el.dataset.check]=el.checked);event(x,'checklist_save','数学核验清单');save(x);toast('检查结果已保存')}}
function renderEvidence(){const s=load();setRoot(shell('student','s4',head('过程证据包','把测量、计算、图像、推理和外部资料与模型版本连接起来。','<a class="btn" href="stage4.html">返回阶段4</a>','阶段4 · 三级页面')+`<div class="grid cols-2"><section class="card"><h2>已有证据</h2>${s.evidence.map((e,i)=>`<div class="evidence-item"><span>${badge(e.type,e.verified?'ok':'warn')}</span><div><b>${esc(e.text)}</b><div class="muted small">来源：${esc(e.source)}</div></div><button class="btn sm" data-verify="${i}">${e.verified?'已核验':'标为已核验'}</button></div>`).join('')}<div class="toolbar">${btn('新增证据','primary','addEvidence')}</div></section><section class="card"><h2>证据链检查</h2><div class="mini-stat"><span>已核验</span><b>${s.evidence.filter(e=>e.verified).length}</b></div><div class="mini-stat"><span>待核验</span><b>${s.evidence.filter(e=>!e.verified).length}</b></div><div class="mini-stat"><span>关联模型版本</span><b>${s.versions.at(-1)?.v||'尚未保存'}</b></div><div class="divider"></div><div class="info">证据包帮助教师和小组回看“结论基于什么”。系统不把证据数量直接转成成绩。</div></section></div>`));document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=()=>{const x=load();x.evidence[+b.dataset.verify].verified=true;event(x,'evidence_verify',x.evidence[+b.dataset.verify].text);save(x);renderEvidence()});document.querySelector('#addEvidence').onclick=()=>modal('新增证据',`<div class="field"><label>证据内容</label><textarea id="newEvidence" placeholder="记录本组的计算、测量、图像或推理证据"></textarea></div><div class="field mt8"><label>来源</label><select id="newSource"><option>小组计算</option><option>图像核验</option><option>任务材料</option><option>实测数据</option></select></div><div class="toolbar"><button class="btn primary" id="commitEvidence">加入证据包</button></div>`)}
function renderDiscussion(){const s=load();setRoot(shell('student','s4',head('观点协商与证据型异议','把分歧指向数学对象、依据和待核验点，降低人身化冲突。','<a class="btn" href="stage4.html">返回阶段4</a>','阶段4 · 三级页面')+`<div class="grid cols-2"><section class="card"><h2>低威胁表达模板</h2><div class="task-list"><div class="task"><b>我质疑的是……</b><small>只描述模型、条件、证据或推理。</small></div><div class="task"><b>我的依据是……</b><small>写公式、图像、数据或条件。</small></div><div class="task"><b>我们还需要核验……</b><small>把争议转成可以共同完成的下一步。</small></div></div><div class="field mt12"><label>写一条证据型异议</label><textarea id="debateText" placeholder="我质疑的是……；我的依据是……；我们还需要核验……"></textarea></div><div class="toolbar">${btn('加入讨论记录','primary','addDebate')}</div></section><section class="card"><h2>讨论记录</h2><div class="timeline">${s.debate.length?s.debate.map(x=>`<div class="tl"><div class="tl-time">${esc(x.who)}</div><div class="tl-body">${esc(x.text)}<br><span class="muted small">回应：${esc(x.reply)}</span></div></div>`).join(''):'<div class="empty">尚无讨论记录</div>'}</div><div class="divider"></div><button class="btn danger" id="teacherConflict">复杂冲突转教师</button><div class="note mt12">嘲笑、持续争执、关系冲突或纪律问题直接由教师处理，AI不承担关系性调解。</div></section></div>`));document.querySelector('#addDebate').onclick=()=>{const text=document.querySelector('#debateText').value.trim();if(!text){toast('请先填写异议内容');return}const x=load();x.debate.push({who:'记录者',text,reply:'待组内回应'});event(x,'debate_save','证据型异议');save(x);toast('讨论记录已保存');setTimeout(renderDiscussion,250)};document.querySelector('#teacherConflict').onclick=()=>askTeacher('复杂冲突需要教师介入')}
function renderVersions(){const s=load();setRoot(shell('student','history',head('模型与过程版本','保留“改了什么、为什么改”，支持成果反思和教师回看。','<a class="btn" href="stage4.html">返回阶段4</a>','版本化')+`<section class="card"><h2>模型版本</h2><div class="timeline">${s.versions.length?s.versions.map((v,i)=>`<div class="tl"><div class="tl-time">${v.time}</div><div class="tl-body"><b>${v.v}</b> ${badge(i===s.versions.length-1?'当前':'历史',i===s.versions.length-1?'ok':'')}<br>${esc(v.note)}<br><span class="mono small">${esc(v.model||'')}</span></div></div>`).join(''):'<div class="empty">尚未保存模型版本</div>'}</div><div class="note mt12">版本变化用于学习证据，不做个人排名。</div></section>`))}
function renderTools(){setRoot(shell('student','s4',head('数学工具','用于机械计算和结果核验，不能替代模型选择和解释。','<a class="btn" href="stage4.html">返回阶段4</a>','阶段4 · 工具性支持')+`<div class="grid cols-2"><section class="card"><h2>快速计算</h2><div class="field"><label>表达式（支持 + - * / 与括号）</label><input id="calcIn" placeholder="例如：(12+8)/4"></div><div class="toolbar">${btn('计算','primary','calcBtn')}</div><div class="success" id="calcOut">等待输入</div></section><section class="card"><h2>工具边界</h2><div class="locked-rule"><span>重复计算</span>${badge('可辅助','ok')}</div><div class="locked-rule mt8"><span>代入核验</span>${badge('可辅助','ok')}</div><div class="locked-rule mt8"><span>模型选择/证明路线</span>${badge('学生决定','blue')}</div><div class="locked-rule mt8"><span>最终数学解释</span>${badge('学生决定','blue')}</div></section></div>`));document.querySelector('#calcBtn').onclick=()=>{const val=document.querySelector('#calcIn').value;if(!/^[0-9+\-*/().\s]+$/.test(val)){toast('仅接受基础算术表达式');return}try{const result=safeCalculate(val);document.querySelector('#calcOut').textContent='结果：'+result;const s=load();event(s,'math_tool','calculator');save(s)}catch(e){toast(e.message||'表达式无法计算')}}}
function renderProduct(){const s=load();setRoot(shell('student','s5',head('成果整理','按“问题—模型—证据—结论—局限”组织已有内容。','<a class="btn" href="stage5.html">返回阶段5</a>','阶段5 · 二级页面')+`<div class="grid cols-2"><section class="card"><div class="field"><label>成果标题</label><input data-p="title" value="${esc(s.product.title)}"></div><div class="field mt8"><label>服务对象</label><input data-p="audience" value="${esc(s.product.audience)}"></div><div class="field mt8"><label>核心结论（由小组填写）</label><textarea data-p="claim">${esc(s.product.claim)}</textarea></div><div class="field mt8"><label>局限与现实条件</label><textarea data-p="limitations">${esc(s.product.limitations)}</textarea></div><div class="toolbar">${btn('保存成果草稿','primary','saveProduct')}</div></section><section class="card"><h2>表达完整性检查</h2><div class="task-list"><div class="task flex"><b>问题与情境</b>${badge('有','ok')}</div><div class="task flex"><b>变量和模型</b>${badge('有草稿','ok')}</div><div class="task flex"><b>取值范围和现实限制</b>${badge('待补强','warn')}</div><div class="task flex"><b>证据与验证</b>${badge('进行中','blue')}</div><div class="task flex"><b>结论与局限</b>${badge('有草稿','ok')}</div></div><div class="info mt12">系统可以提醒缺项、单位和证据引用，不自动替小组写最终答辩稿。</div></section></div>`));document.querySelector('#saveProduct').onclick=()=>{const x=load();document.querySelectorAll('[data-p]').forEach(el=>x.product[el.dataset.p]=el.value);event(x,'product_save','成果草稿');save(x);toast('成果草稿已保存')}}
function renderRehearsal(){const s=load();setRoot(shell('student','s5',head('展示预演','在公开表达前留出准备和组内修订空间。','<a class="btn" href="stage5.html">返回阶段5</a>','阶段5 · 二级页面')+`<div class="grid cols-2"><section class="card"><h2>答辩结构</h2><ol><li>说明项目问题和现实限制</li><li>解释变量、数量关系和数学模型</li><li>展示证据、验证方法与结果</li><li>说明结论、适用范围和局限</li></ol><div class="field"><label>组内预演记录</label><textarea id="rehearsal" placeholder="记录分工、发现的问题和修改计划">${esc(s.product.rehearsal||'')}</textarea></div><div class="toolbar">${btn('保存预演记录','primary','saveRehearsal')}</div></section><section class="card"><h2>公开表达前检查</h2><div class="task-list"><label class="task"><input type="checkbox"> 每位成员知道自己负责回答的数学问题</label><label class="task"><input type="checkbox"> 图表标题、单位和变量含义清楚</label><label class="task"><input type="checkbox"> 能解释验证方法和结论依据</label><label class="task"><input type="checkbox"> 能说明模型没有考虑哪些现实因素</label></div><div class="note mt12">准备、组内试答和分工有助于降低无准备公开暴露。</div></section></div>`));document.querySelector('#saveRehearsal').onclick=()=>{const x=load();x.product.rehearsal=document.querySelector('#rehearsal').value;event(x,'rehearsal_save','组内预演');save(x);toast('预演记录已保存')}}
function renderReflection(){const s=load(),saved=(s.product.reflection||'').split('\n');setRoot(shell('student','s5',head('反思与迁移','回看模型版本、提示使用、角色轮换和“自己完成的数学工作”。','<a class="btn" href="stage5.html">返回阶段5</a>','阶段5 · 二级页面')+`<div class="grid cols-2"><section class="card"><h2>过程事实回看</h2><div class="mini-stat"><span>模型版本</span><b>${s.versions.length}</b></div><div class="mini-stat"><span>AI提示</span><b>${s.hintUsed}次</b></div><div class="mini-stat"><span>最高提示层级</span><b>${s.helpHistory.at(-1)?.level||'L0'}</b></div><div class="mini-stat"><span>角色轮换</span><b>${s.roleRound-1}次</b></div><div class="mini-stat"><span>已核验证据</span><b>${s.evidence.filter(e=>e.verified).length}</b></div><div class="note mt12">这些记录只作为反思事实，不直接解释为情绪、能力或最终成绩。</div></section><section class="card"><h2>小组反思</h2><div class="field"><label>我们自己完成的关键数学工作</label><textarea id="r1">${esc(saved[0]||'')}</textarea></div><div class="field mt8"><label>提示真正帮助了什么</label><textarea id="r2">${esc(saved[1]||'')}</textarea></div><div class="field mt8"><label>下次遇到类似问题准备怎样做</label><textarea id="r3">${esc(saved[2]||'')}</textarea></div><div class="toolbar">${btn('保存反思','primary','saveReflection')}</div></section></div>`));document.querySelector('#saveReflection').onclick=()=>{const x=load();x.product.reflection=[document.querySelector('#r1').value,document.querySelector('#r2').value,document.querySelector('#r3').value].join('\n');event(x,'reflection_save','阶段5反思');save(x);toast('反思已保存')}}
function renderHelp(){const s=load();const aiOK=s.aiOpen;setRoot(shell('student','help',head('提示与求助','已有进展→同伴解释→L1定位→L2结构→L3局部支架→必要时转教师。',`<a class="btn" href="workspace.html">查看已有进展</a>`,'最小充分提示')+`<div class="grid cols-2"><section class="card"><h2>1. 先说明你们做到哪里</h2><div class="field"><label>已经完成</label><textarea id="helpDone" placeholder="写出本组已经完成的推理、计算或验证"></textarea></div><div class="field mt8"><label>具体卡点</label><select id="helpType"><option>任务理解</option><option>变量关系</option><option>数学建模</option><option>证明推理</option><option>数据处理</option><option>计算核验</option><option>表达与解释</option></select></div><div class="field mt8"><label>用一句话描述卡点</label><textarea id="helpIssue" placeholder="描述一个具体、可检查的问题"></textarea></div><div class="checkbox-row mt12"><label><input type="checkbox" id="peerTried"> 已请一位组员先解释</label><label><input type="checkbox" id="checkedWork"> 已检查共享工作区</label></div><div class="toolbar">${btn(aiOK?'请求下一层提示':'AI已暂停','primary','requestHint',aiOK?'':'disabled')} ${btn('转教师','ghost','askTeacher')}</div><div class="${aiOK?'info':'note'}">${aiOK?`本节提示额度 ${s.hintUsed}/${s.hintQuota}，最高允许L${s.maxHintLevel}。模型不可用时自动返回教师预设支架。`:'AI已暂停，可继续使用工作区或转教师。'}</div></section><section class="card"><h2>2. 最近提示链</h2>${s.helpHistory.length?s.helpHistory.slice().reverse().map(h=>`<div class="callout mt8"><div class="status-row"><b>${h.level}</b>${badge(h.type,'blue')}<span class="muted small">${h.time}</span></div><div class="small mt8"><b>你们问：</b>${esc(h.prompt)}</div><div class="mt8"><b>提示：</b>${esc(h.reply)}</div></div>`).join(''):'<div class="empty">还没有提示记录</div>'}<div class="divider"></div><h3>层级规则</h3><div class="mini-stat"><span>L1</span><b>目标/条件定位</b></div><div class="mini-stat"><span>L2</span><b>子问题/表征结构</b></div><div class="mini-stat"><span>L3</span><b>局部例子/一步验证</b></div><div class="mini-stat"><span>L4</span><b>教师接管</b></div></section></div>`));document.querySelector('#requestHint').onclick=async()=>{const done=document.querySelector('#helpDone').value.trim(),issue=document.querySelector('#helpIssue').value.trim(),type=document.querySelector('#helpType').value;if(!done||!issue){toast('先写出已有进展和具体卡点');return}const button=document.querySelector('#requestHint');button.disabled=true;button.textContent='正在生成提示…';try{const result=await api('/api/hints',{method:'POST',body:JSON.stringify({done,issue,type,peerTried:document.querySelector('#peerTried').checked,checkedWork:document.querySelector('#checkedWork').checked})});if(result.escalated){toast(result.message)}else{toast(result.source==='deepseek'?`${result.level}提示已返回`:'模型不可用，已返回教师预设支架')}const refreshed=await api('/api/state');_state=Object.assign(defaultState(),refreshed.state||{});renderHelp()}catch(e){toast(e.message);button.disabled=false;button.textContent='请求下一层提示'}};document.querySelector('#askTeacher').onclick=()=>askTeacher('学生主动求助')}
async function askTeacher(reason){try{await api('/api/escalations',{method:'POST',body:JSON.stringify({reason})});toast('已进入教师处理队列')}catch(e){toast(e.message)}}
function renderGroup(){const s=load();setRoot(shell('student','group',head('小组协作与角色','角色、个人先想、同伴解释和非标签化提醒共同支持数学责任分担。',`<button class="btn primary" id="rotate">轮换角色</button>`,'协作支持')+`<div class="grid cols-2"><section class="card"><h2>当前角色 · 第${s.roleRound}轮</h2><table class="table"><thead><tr><th>成员</th><th>角色</th><th>数学责任</th></tr></thead><tbody>${s.members.map((m,i)=>`<tr><td>${m||'成员'+(i+1)}</td><td><b>${s.roles[i]}</b></td><td>${['形成模型/图示','质疑条件/范围/证据','保存证据与修改理由','负责组内复述/展示'][i]}</td></tr>`).join('')}</tbody></table><div class="note mt12">系统提醒“缺少哪类数学责任”，不评价谁积极、谁消极。</div></section><section class="card"><h2>个人先想与同伴解释</h2>${s.members.map((m,i)=>`<div class="task"><b>${m||'成员'+(i+1)}</b><small>${esc(s.firstThoughts[i]||'')}</small></div>`).join('')}<div class="toolbar"><a class="btn" href="stage2-understanding.html">更新个人先想</a><a class="btn" href="help.html">同伴解释后再求助</a></div></section></div>`));document.querySelector('#rotate').onclick=()=>{const x=load();x.roles.unshift(x.roles.pop());x.roleRound++;event(x,'role_rotate',`轮次${x.roleRound}`);save(x);toast('角色已轮换');setTimeout(renderGroup,250)}}
function renderHistory(){const s=load();setRoot(shell('student','history',head('过程与版本回看','回看阶段提交、模型版本、提示链和关键协作记录，为反思提供事实。','<a class="btn" href="stage5-reflection.html">进入反思</a>','过程证据')+`<div class="grid cols-3">${metric('阶段提交',Object.values(s.stageSubmitted).filter(Boolean).length+'/5','当前阶段3')}${metric('模型版本',s.versions.length,'可回看修改理由')}${metric('提示使用',s.hintUsed,'不直接解释为能力')}</div><div class="grid cols-2 mt16"><section class="card"><h2>版本时间线</h2><div class="timeline">${s.versions.map(v=>`<div class="tl"><div class="tl-time">${v.time}</div><div class="tl-body"><b>${v.v}</b><br>${esc(v.note)}</div></div>`).join('')}</div></section><section class="card"><h2>提示时间线</h2>${s.helpHistory.map(h=>`<div class="tl"><div class="tl-time">${h.time}</div><div class="tl-body"><b>${h.level} · ${h.type}</b><br>${esc(h.reply)}</div></div>`).join('')||'<div class="empty">无提示记录</div>'}</section></div>`))}
function renderStudentGovernance(){setRoot(shell('student','gov',head('数据使用说明','本页说明平台固定的数据政策与功能边界，不是自动检测或实时判断结果。','','使用边界')+`<div class="grid cols-2"><section class="card"><h2>使用功能时记录</h2><div class="locked-rule"><span>阶段进入与提交</span>${badge('记录','ok')}</div><div class="locked-rule mt8"><span>主动求助与提示层级</span>${badge('记录','ok')}</div><div class="locked-rule mt8"><span>共享工作区版本</span>${badge('记录','ok')}</div><div class="locked-rule mt8"><span>教师控制与处理</span>${badge('记录','ok')}</div><div class="note mt12">课堂数据导出使用去标识化小组编号。</div></section><section class="card"><h2>平台明确禁用</h2><div class="locked-rule"><span>持续录音录像</span>${badge('禁用','danger')}</div><div class="locked-rule mt8"><span>自动情绪识别</span>${badge('禁用','danger')}</div><div class="locked-rule mt8"><span>自动能力标签</span>${badge('禁用','danger')}</div><div class="locked-rule mt8"><span>AI自动最终评分</span>${badge('禁用','danger')}</div><div class="info mt12">AI暂停或网络故障时，共享工作区和项目任务仍可继续使用。</div></section></div>`))}
// ---------- Teacher pages ----------
function teacherMetrics(){const s=load(),total=s.groups.reduce((a,g)=>a+(Number(g.help)||0),0),average=s.groups.length?(total/s.groups.length).toFixed(1):'0.0';return `<div class="grid cols-4">${metric('当前阶段',`${s.currentStage}/5`,stage(s.currentStage).full)}${metric('需要教师',s.queue.filter(q=>!q.resolved).length+'组',s.queue.filter(q=>!q.resolved).map(q=>q.group+'组').join('、')||'当前没有')}${metric('共性卡点',s.common.length+'项',s.common[0]?.title||'尚未形成')}${metric('AI助用',total,`平均 ${average}次/组`)}</div>`}
function groupTable(s,limit=10){return `<table class="table"><thead><tr><th>组</th><th>阶段</th><th>最近状态</th><th>最近产出</th><th>求助</th><th>最高提示</th><th>教师</th><th>进度</th></tr></thead><tbody>${s.groups.slice(0,limit).map(g=>`<tr><td><a class="link" href="group-detail.html?g=${g.id}">${g.id}组</a></td><td>${g.stage}</td><td>${badge(g.status,g.teacher?'danger':g.status.includes('检查')?'warn':'ok')}</td><td>${esc(g.latest)}</td><td>${g.help}</td><td>${g.maxHint?'L'+g.maxHint:'—'}</td><td>${g.teacher?'<b>需介入</b>':'—'}</td><td><div class="progress" style="min-width:100px"><i style="width:${g.progress}%"></i></div></td></tr>`).join('')}</tbody></table>`}
function renderTeacherDashboard(){const s=load();if(!s.project){setRoot(shell('teacher','home',head('开始配置课堂',s.groupCount+'个小组访问空间已创建；项目内容尚未配置。','<a class="btn primary" href="project.html">创建项目</a>','教师总控端')+`<div class="grid cols-3">${metric('小组空间',s.groupCount+'组','来自初始化设置')}${metric('项目','未创建','配置后开放课堂阶段')}${metric('过程数据',s.events.length+'条','当前小组事件')}</div><section class="card mt16"><div class="empty"><h2>没有课堂项目</h2><p>请先填写班级、项目名称、数学主题和课程目标。平台不会自动填入示例项目。</p></div></section>`));return}setRoot(shell('teacher','home',head(`课堂总览 · ${esc(s.className||'未填写班级名称')}`,`项目：${esc(s.project||'尚未创建项目')} · ${s.groupCount}个小组 · 当前阶段：${stage(s.currentStage).full}`,`<button class="btn ${s.aiOpen?'green':'danger'}" id="aiToggle">AI${s.aiOpen?'已开放':'已暂停'}</button><a class="btn primary" href="stages.html">阶段控制</a><a class="btn" href="broadcast.html">广播提示</a>`,'教师总控端')+teacherMetrics()+`<div class="grid cols-2 mt16"><section class="card"><div class="page-head"><div><h2>小组态势</h2><p>仅显示教学决策需要的信息，不显示自动心理判断。</p></div><a class="btn sm" href="groups.html">查看全部</a></div>${groupTable(s,6)}</section><section class="card"><h2>共性问题</h2>${s.common.map(c=>`<div class="task"><b>${esc(c.title)}</b><small>${c.groups.length}组出现 · ${esc(c.note)}</small><div class="toolbar"><a class="btn sm" href="common.html">查看证据</a></div></div>`).join('')}<div class="divider"></div><h3>教师队列</h3>${s.queue.filter(q=>!q.resolved).map(q=>`<div class="task flex"><div><b>${q.group}组 · ${q.type}</b><small>${esc(q.reason)}</small></div>${badge(q.priority,q.priority==='高'?'danger':'warn')}</div>`).join('')||'<div class="success">当前没有待处理事项。</div>'}</section></div>`));document.querySelector('#aiToggle').onclick=()=>{const x=load();x.aiOpen=!x.aiOpen;audit(x,'教师',x.aiOpen?'开放AI':'暂停AI','全班');event(x,'teacher_control',x.aiOpen?'AI_ON':'AI_OFF','CLASS');save(x);toast(`AI已${x.aiOpen?'开放':'暂停'}`);setTimeout(renderTeacherDashboard,250)}}
function renderProject(){const s=load(),c=s.teacherConfig;setRoot(shell('teacher','project',head('项目与支架配置','课前配置项目、五阶段产出、提示额度与项目级知识约束。','<a class="btn" href="template.html">从模板复制</a>','课前编排')+`<div class="grid cols-2"><section class="card"><h2>项目基本信息</h2><div class="form-grid"><div class="field"><label>班级</label><input id="pcClass" value="${esc(s.className)}"></div><div class="field"><label>项目名称</label><input id="pcProject" value="${esc(s.project)}"></div><div class="field"><label>数学主题</label><input id="pcTopic" value="${esc(c.mathTopic)}"></div><div class="field"><label>课时类型</label><select id="pcType"><option value="" disabled ${!s.projectType?"selected":""}>请选择课时类型</option><option ${s.projectType==='微型项目'?'selected':''}>微型项目</option><option ${s.projectType==='标准项目'?'selected':''}>标准项目</option><option ${s.projectType==='深度项目'?'selected':''}>深度项目</option></select></div></div><div class="field mt8"><label>课程标准/单元目标</label><textarea id="pcStd">${esc(c.standard)}</textarea></div><div class="field mt8"><label>最终成果</label><input id="pcProduct" value="${esc(c.finalProduct)}"></div><div class="toolbar">${btn('保存项目配置','primary','saveProject')}</div></section><section class="card"><h2>课堂技术规则</h2><div class="mini-stat"><span>每组设备</span><b>1台横屏平板</b></div><div class="mini-stat"><span>本节提示额度</span><b>${s.hintQuota}次/组</b></div><div class="mini-stat"><span>最高生成式提示</span><b>L${s.maxHintLevel}</b></div><div class="mini-stat"><span>连续无效</span><b>转教师队列</b></div><div class="mini-stat"><span>模型/网络超时</span><b>静态支架降级</b></div><div class="divider"></div><a class="btn" href="scaffolds.html">配置提示模板</a> <a class="btn" href="knowledge.html">管理知识库</a></section></div>`));document.querySelector('#saveProject').onclick=()=>{const x=load();x.className=document.querySelector('#pcClass').value;x.project=document.querySelector('#pcProject').value;x.teacherConfig.mathTopic=document.querySelector('#pcTopic').value;x.projectType=document.querySelector('#pcType').value;x.teacherConfig.standard=document.querySelector('#pcStd').value;x.teacherConfig.finalProduct=document.querySelector('#pcProduct').value;audit(x,'教师','修改项目配置',x.project);event(x,'config_save','project','CLASS');save(x);toast('项目配置已保存')}}
function renderTemplate(){const s=load();const templates=[['微型项目','2—3课时','压缩阶段1/2，保留五阶段逻辑与阶段产出','适合单一数学化/模型验证任务'],['标准项目','5—7课时','五阶段完整实施，阶段3/4各至少1课时','按课堂课时选择'],['深度项目','8—12课时','阶段3/4允许多轮模型与证据迭代','适合跨单元或实测项目']];setRoot(shell('teacher','template',head('项目模板','根据中国初中课时条件选择微型、标准或深度项目，五阶段逻辑保持一致。','<a class="btn" href="project.html">返回项目配置</a>','课时弹性')+`<div class="grid cols-3">${templates.map(t=>`<section class="card"><h2>${t[0]}</h2><div class="kpi-band"><span class="kpi"><b>${t[1]}</b></span></div><p>${t[2]}</p><div class="note">${t[3]}</div><div class="toolbar"><button class="btn ${s.projectType===t[0]?'green':'primary'}" data-template="${t[0]}">${s.projectType===t[0]?'当前模板':'应用模板'}</button></div></section>`).join('')}</div><section class="card mt16"><h2>五阶段共同骨架</h2>${stageStripTeacher(s)}</section>`));document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{const x=load();x.projectType=b.dataset.template;x.projectHours=templates.find(t=>t[0]===x.projectType)?.[1]||'';audit(x,'教师','切换项目模板',x.projectType);save(x);toast('已应用'+x.projectType);setTimeout(renderTemplate,250)});}
function renderKnowledge(){const s=load();setRoot(shell('teacher','knowledge',head('项目知识库','只使用教师审核的任务资料、课程标准和项目参考内容约束AI输出。','<a class="btn" href="project.html">返回项目配置</a>','数学可靠性')+`<div class="grid cols-2"><section class="card"><h2>已审核材料</h2>${s.teacherConfig.knowledge.length?s.teacherConfig.knowledge.map(x=>`<div class="task flex"><div><b>${esc(x)}</b><small>教师审核项目资料</small></div>${badge('已审核','ok')}</div>`).join(''):'<div class="empty">尚未上传项目资料</div>'}<div class="toolbar"><input id="knowledgeFile" type="file" accept=".pdf,.docx,.txt,.md,.csv,.png,.jpg,.jpeg,.webp" hidden>${btn('上传材料','primary','uploadMaterial')}</div></section><section class="card"><h2>生成约束</h2><div class="locked-rule"><span>优先检索项目包与教师审核知识</span>${badge('启用','ok')}</div><div class="locked-rule mt8"><span>首次响应禁止完整模型/证明</span>${badge('锁定','blue')}</div><div class="locked-rule mt8"><span>低置信度/材料冲突</span>${badge('转教师','warn')}</div><div class="locked-rule mt8"><span>最终数学结论</span>${badge('人工核验','blue')}</div><div class="note mt12">文本、Markdown、CSV与Word内容可进入提示约束；PDF和图片作为教师审核材料保存，需由教师在项目说明中补充关键文字。</div></section></div>`));const input=document.querySelector('#knowledgeFile');document.querySelector('#uploadMaterial').onclick=()=>input.click();input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>10*1024*1024){toast('单个文件不能超过10MB');return}const button=document.querySelector('#uploadMaterial');button.disabled=true;button.textContent='正在上传…';try{const content=(await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)}));await api('/api/files',{method:'POST',body:JSON.stringify({name:file.name,content})});const refreshed=await api('/api/state');_state=Object.assign(defaultState(),refreshed.state||{});toast('材料已上传并加入知识库');renderKnowledge()}catch(e){toast(e.message);button.disabled=false;button.textContent='上传材料'}}}
function renderScaffolds(){const s=load();setRoot(shell('teacher','scaffold',head('提示与支架规则','教师预设可编辑的静态支架和生成式提示边界，学生无需编写提示词。','<a class="btn" href="project.html">返回项目配置</a>','条件性AI')+`<div class="grid cols-2"><section class="card"><h2>分层提示规则</h2><table class="table"><thead><tr><th>层级</th><th>用途</th><th>允许内容</th><th>禁止内容</th></tr></thead><tbody><tr><td>L1</td><td>定位</td><td>目标、已知未知、关键条件</td><td>完整方法</td></tr><tr><td>L2</td><td>结构</td><td>子问题、表征、验证维度</td><td>完整模型</td></tr><tr><td>L3</td><td>局部支架</td><td>一步示例、局部模板</td><td>最终证明/结论</td></tr><tr><td>L4</td><td>教师</td><td>转教师并附已有进展</td><td>AI继续加码</td></tr></tbody></table><div class="toolbar"><label>最高层级 <select id="maxLevel"><option value="2" ${s.maxHintLevel===2?'selected':''}>L2</option><option value="3" ${s.maxHintLevel===3?'selected':''}>L3</option></select></label><label>提示额度 <select id="quota"><option>2</option><option ${s.hintQuota===3?'selected':''}>3</option><option>4</option></select></label>${btn('保存规则','primary','saveRules')}</div></section><section class="card"><h2>静态降级支架</h2>${s.teacherConfig.staticHints.map((h,i)=>`<div class="field mt8"><label>静态支架 ${i+1}</label><textarea data-static="${i}">${esc(h)}</textarea></div>`).join('')}<div class="toolbar">${btn('保存静态支架','green','saveStatic')}</div><div class="note">模型不可用时，学生仍能获得教师预设的轻量提示，课堂不因AI故障中断。</div></section></div>`));document.querySelector('#saveRules').onclick=()=>{const x=load();x.maxHintLevel=+document.querySelector('#maxLevel').value;x.hintQuota=+document.querySelector('#quota').value;audit(x,'教师','修改提示规则',`最高L${x.maxHintLevel};额度${x.hintQuota}`);save(x);toast('提示规则已保存')};document.querySelector('#saveStatic').onclick=()=>{const x=load();document.querySelectorAll('[data-static]').forEach(el=>x.teacherConfig.staticHints[+el.dataset.static]=el.value);audit(x,'教师','修改静态支架','3条');save(x);toast('静态支架已保存')}}
function renderStagesTeacher(){const s=load(),ready=s.groups.filter(g=>g.progress>=55).length,issueCount=s.common.length,openCount=s.queue.filter(q=>!q.resolved).length;setRoot(shell('teacher','stages',head('课堂阶段控制','教师决定阶段开放、暂停、推进与课堂广播，AI暂停后学生工作区仍可使用。',`<button class="btn ${s.aiOpen?'green':'danger'}" id="aiToggle">AI${s.aiOpen?'开放':'暂停'}</button>`,'课中编排')+stageStripTeacher(s)+`<div class="grid cols-2 mt16"><section class="card"><h2>当前阶段控制</h2><div class="mini-stat"><span>当前阶段</span><b>${stage(s.currentStage).full}</b></div><div class="mini-stat"><span>建议产出</span><b>${stage(s.currentStage).output}</b></div><div class="mini-stat"><span>仍未完成必要产出</span><b>${s.groups.filter(g=>g.progress<55).map(g=>g.id+'组').join('、')||'无'}</b></div><div class="toolbar">${btn('暂停本阶段','warn','pauseStage')} ${btn('推进到下一阶段','primary','nextStage',s.currentStage>=5?'disabled':'')} </div></section><section class="card"><h2>阶段转换检查</h2><div class="task-list"><div class="task flex"><b>关键产出已有代表性版本</b>${badge(ready+'/'+s.groups.length+'组','blue')}</div><div class="task flex"><b>共性数学误读已处理</b>${badge(issueCount?issueCount+'项':'无','warn')}</div><div class="task flex"><b>需要教师组已定位</b>${badge(openCount+'项','danger')}</div><div class="task flex"><b>下一阶段角色轮换</b>${badge(s.groups.length?'已配置':'待配置','ok')}</div></div><div class="note mt12">转换门提供信息，推进决定权保留给教师。</div></section></div>`));document.querySelector('#aiToggle').onclick=()=>{const x=load();x.aiOpen=!x.aiOpen;audit(x,'教师',x.aiOpen?'开放AI':'暂停AI','全班');event(x,'teacher_control',x.aiOpen?'AI_ON':'AI_OFF','CLASS');save(x);toast('AI状态已更新');setTimeout(renderStagesTeacher,250)};document.querySelector('#pauseStage').onclick=()=>{const x=load();x.stagePaused=!x.stagePaused;audit(x,'教师',x.stagePaused?'暂停阶段':'恢复阶段',stage(x.currentStage).full);save(x);toast(x.stagePaused?'阶段已暂停':'阶段已恢复');setTimeout(renderStagesTeacher,250)};const nb=document.querySelector('#nextStage');if(nb)nb.onclick=()=>{const x=load();if(x.currentStage<5){x.currentStage++;x.stagePaused=false;audit(x,'教师','推进阶段',stage(x.currentStage).full);event(x,'stage_enter',stage(x.currentStage).full,'CLASS',x.currentStage);save(x);toast('已推进到阶段'+x.currentStage);setTimeout(renderStagesTeacher,250)}}}
function stageStripTeacher(s){return `<div class="stage-strip">${STAGES.map(x=>`<div class="stage-card ${x.n<s.currentStage?'done':''} ${x.n===s.currentStage?'current':''}"><div class="stage-no">阶段 ${x.n}</div><div class="stage-name">${x.name}</div><div class="stage-state">${x.n<s.currentStage?'已完成':x.n===s.currentStage?(s.stagePaused?'已暂停':'当前进行'):'未开放'}</div><div class="stage-output">${x.output}</div></div>`).join('')}</div>`}
function renderGroups(){const s=load();setRoot(shell('teacher','groups',head('小组态势','聚合阶段、产出、求助、提示和教师标记，避免心理标签和个人排行榜。','','多组并行')+teacherMetrics()+`<section class="card mt16"><div class="table-wrap">${groupTable(s,10)}</div><div class="note mt12">“最近状态”来自阶段提交、求助、提示和教师标记等教学事件，不是自动情绪或能力判断。</div></section>`))}
function renderGroupDetail(){const s=load(),params=new URLSearchParams(location.search),gid=+(params.get('g')||1),g=s.groups.find(x=>x.id===gid)||{id:gid,stage:s.currentStage,status:'准备中',latest:'尚未保存',help:0,maxHint:0,progress:0,issue:''};setRoot(shell('teacher','detail',head(`${g.id}组 · 过程证据详情`,`${g.status} · ${g.latest}`,`<a class="btn" href="groups.html">返回小组态势</a><a class="btn primary" href="queue.html">教师队列</a>`,'可追溯详情')+`<div class="grid cols-3">${metric('阶段',g.stage+'/5',stage(g.stage).name)}${metric('求助',g.help+'次','最高'+(g.maxHint?'L'+g.maxHint:'无'))}${metric('模型版本',s.versions.length+'个',s.versions.at(-1)?.v||'尚未保存')}</div><div class="grid cols-2 mt16"><section class="card"><h2>阶段产出</h2><div class="mini-stat"><span>任务理解</span><b>${s.stageSubmitted[2]?'已提交':'进行中'}</b></div><div class="mini-stat"><span>变量/关系</span><b>${s.workspace.relation?'已保存':'尚未保存'}</b></div><div class="mini-stat"><span>当前卡点</span><b>${esc(g.issue||'—')}</b></div><div class="callout mt12"><b>模型记录：</b><br>${esc(s.workspace.model||'尚未保存')}<br><span class="muted">${esc(s.workspace.evidence||'')}</span></div></section><section class="card"><h2>提示链与教师处理</h2>${s.helpHistory.length?s.helpHistory.map(h=>`<div class="task"><b>${h.level} · ${h.type}</b><small>${esc(h.reply)}</small></div>`).join(''):'<div class="empty">此小组无提示记录</div>'}<div class="toolbar">${btn('记录教师介入','primary','teacherNote')}</div><div class="note">任何自动摘要都应可回到原始阶段产出和提示记录。</div></section></div>`));document.querySelector('#teacherNote').onclick=()=>modal('记录教师介入',`<div class="field"><label>处理方式</label><select id="noteType"><option>个别点拨</option><option>全班讲解</option><option>继续观察</option><option>暂停AI</option></select></div><div class="field mt8"><label>教师短备注</label><textarea id="noteText" placeholder="记录处理方式和后续观察点"></textarea></div><div class="toolbar"><button class="btn primary" id="saveTeacherNote">保存处理</button></div>`)}
function renderQueue(){const s=load();setRoot(shell('teacher','queue',head('教师升级队列','连续无效、高阶数学判断、复杂冲突和系统不确定性进入教师队列。','','教师接管')+`<section class="card"><table class="table"><thead><tr><th>优先级</th><th>组</th><th>类型</th><th>原因</th><th>进入时间</th><th>处理</th></tr></thead><tbody>${s.queue.map(q=>`<tr><td>${badge(q.priority,q.priority==='高'?'danger':'warn')}</td><td><a class="link" href="group-detail.html?g=${q.group}">${q.group}组</a></td><td>${q.type}</td><td>${esc(q.reason)}</td><td>${q.time}</td><td>${q.resolved?badge('已处理','ok'):`<button class="btn sm primary" data-resolve="${q.id}">标记已处理</button>`}</td></tr>`).join('')}</tbody></table></section>`));document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{const x=load();const q=x.queue.find(q=>q.id===b.dataset.resolve);q.resolved=true;audit(x,'教师','处理教师队列',`${q.group}组 · ${q.type}`);event(x,'teacher_resolve',q.id,'G'+String(q.group).padStart(2,'0'));save(x);toast('已标记处理');setTimeout(renderQueue,250)});}
function renderCommon(){const s=load();setRoot(shell('teacher','common',head('共性问题','按数学主题聚合多组相似卡点，同时保留代表性已有进展供教师判断。','<a class="btn primary" href="broadcast.html">准备共性澄清</a>','多组聚合')+`<div class="grid cols-3">${s.common.map(c=>`<section class="card"><div class="eyebrow">${c.id} · ${c.groups.length}组</div><h2>${esc(c.title)}</h2><p>${esc(c.note)}</p><div class="chips">${c.groups.map(g=>`<a class="chip" href="group-detail.html?g=${g}">${g}组</a>`).join('')}</div><div class="note mt12">建议：${esc(c.action)}</div></section>`).join('')}</div><section class="card mt16"><h2>聚合规则说明</h2><p>系统使用阶段、求助主题、教师标记和相似文本形成共性卡点。它不通过情绪识别或个人画像决定谁“需要帮助”。教师可忽略聚合结果，继续按课堂观察判断。</p></section>`))}
function renderBroadcast(){const s=load();setRoot(shell('teacher','broadcast',head('广播与共性澄清','教师向全班发送短提示、阶段提醒或共性数学澄清。','<a class="btn" href="common.html">查看共性问题</a>','教师主动调控')+`<div class="grid cols-2"><section class="card"><div class="field"><label>发送对象</label><input value="全班${s.groupCount}组" readonly></div><div class="field mt8"><label>提示类型</label><select><option>共性数学澄清</option><option>阶段提醒</option><option>时间提醒</option><option>成果要求</option></select></div><div class="field mt8"><label>广播内容</label><textarea id="bcText">${esc(s.broadcast)}</textarea></div><div class="toolbar">${btn('发送广播','primary','sendBc')} ${btn('清空','ghost','clearBc')}</div></section><section class="card"><h2>学生端预览</h2><div class="info"><b>教师广播：</b><br><span id="bcPreview">${esc(s.broadcast||'暂无广播')}</span></div><div class="note mt12">广播是教师教学行为。系统只负责同步，不自动生成课堂价值判断。</div></section></div>`));document.querySelector('#sendBc').onclick=()=>{const x=load();x.broadcast=document.querySelector('#bcText').value.trim();if(!x.broadcast){toast('请填写广播内容');return}audit(x,'教师','发送广播',x.broadcast);event(x,'broadcast',x.broadcast,'CLASS');save(x);document.querySelector('#bcPreview').textContent=x.broadcast;toast('广播已发送')};document.querySelector('#clearBc').onclick=()=>{const x=load();x.broadcast='';save(x);renderBroadcast()}}
function renderEvaluation(){const s=load(),gid=Number(new URLSearchParams(location.search).get('g')||s.groupId||1),ev=s.evaluations[gid]||{};setRoot(shell('teacher','eval',head('成果评价','系统整理证据，教师根据数学质量、解释、证据和协作过程完成最终评价。','','教师最终责任')+`<div class="field mb16"><label>评价小组</label><select id="evalGroup">${Array.from({length:s.groupCount},(_,i)=>`<option value="${i+1}" ${gid===i+1?'selected':''}>${i+1}组</option>`).join('')}</select></div><div class="grid cols-2"><section class="card"><h2>${gid}组成果证据</h2><div class="mini-stat"><span>模型版本</span><b>${s.versions.length}</b></div><div class="mini-stat"><span>已核验证据</span><b>${s.evidence.filter(e=>e.verified).length}</b></div><div class="mini-stat"><span>阶段提交</span><b>${Object.values(s.stageSubmitted).filter(Boolean).length}/5</b></div><div class="mini-stat"><span>提示链</span><b>${s.helpHistory.length}条</b></div><div class="callout mt12"><b>最新模型：</b><br>${esc(s.workspace.model||'尚未提交')}</div></section><section class="card"><h2>教师评价量规（1—4）</h2>${[['模型质量','model'],['证据与验证','evidence'],['数学解释','explain'],['协作与责任','collab']].map(x=>`<div class="field mt8"><label>${x[0]}</label><select data-score="${x[1]}">${[1,2,3,4].map(n=>`<option ${ev[x[1]]===n?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<div class="field mt8"><label>教师评语</label><textarea id="evalComment">${esc(ev.comment||'')}</textarea></div><div class="toolbar">${btn('保存教师评价','primary','saveEval')}</div><div class="note">系统没有AI自动最终评分端口。</div></section></div>`));document.querySelector('#evalGroup').onchange=e=>location.href=`evaluation.html?g=${e.target.value}`;document.querySelector('#saveEval').onclick=()=>{const x=load();x.evaluations[gid]=x.evaluations[gid]||{};document.querySelectorAll('[data-score]').forEach(el=>x.evaluations[gid][el.dataset.score]=+el.value);x.evaluations[gid].comment=document.querySelector('#evalComment').value;audit(x,'教师','保存成果评价',`${gid}组`);event(x,'evaluation_save','教师评价',`G${String(gid).padStart(2,'0')}`,5);save(x);toast('教师评价已保存')}}
function renderReport(){const s=load(),totalHelp=s.groups.reduce((a,g)=>a+(Number(g.help)||0),0),open=s.queue.filter(q=>!q.resolved),completed=Object.values(s.stageSubmitted).filter(Boolean).length;setRoot(shell('teacher','report',head('课后课堂总结','用阶段完成、求助、提示、版本和教师处理形成课堂事实摘要。','<a class="btn" href="export.html">导出课堂数据</a>','课后')+`<div class="grid cols-4">${metric('当前阶段',`${s.currentStage}/5`,stage(s.currentStage).full)}${metric('全班求助',totalHelp,`${s.groups.length}组`)}${metric('待教师处理',open.length,'累计'+s.queue.length)}${metric('共性问题',s.common.length,'数学主题聚合')}</div><div class="grid cols-2 mt16"><section class="card"><h2>课堂事实摘要</h2><div class="task-list"><div class="task"><b>阶段产出</b><small>当前查看小组已提交 ${completed}/5 个阶段产出。</small></div><div class="task"><b>教师升级</b><small>${open.length?open.map(q=>`${q.group}组：${esc(q.reason)}`).join('；'):'当前没有待处理事项。'}</small></div><div class="task"><b>共性问题</b><small>${s.common.length?s.common.map(c=>`${esc(c.title)}（${c.groups.length}组）`).join('；'):'尚未形成共性问题记录。'}</small></div><div class="task"><b>课堂广播</b><small>${esc(s.broadcast||'本节课尚未发送广播。')}</small></div></div><div class="note">这些事实用于教学复盘，不直接解释为学生情绪或能力变化。</div></section><section class="card"><h2>教学复盘建议</h2><div class="task-list"><div class="task"><b>核对系统事件</b><small>结合课堂观察确认阶段、求助和教师处理发生的背景。</small></div><div class="task"><b>记录设计修订理由</b><small>将项目资料、支架规则或课堂流程的修改与证据对应。</small></div><div class="task"><b>保留人工判断</b><small>数学成果和课堂体验结论由教师综合判断。</small></div></div></section></div>`))}
async function renderExport(){
 const s=load(),runtime=await api('/api/runtime'),data=runtime.data,events=runtime.recentEvents||[];
 const range=data.events?(data.firstEventAt+' 至 '+data.lastEventAt):'尚无课堂事件';
 setRoot(shell('teacher','export',head('课堂数据导出','导出文件由服务器根据当前数据库实时生成，不读取前端预设内容。','','数据导出')+
 `<div class="grid cols-4">${metric('事件总数',data.events,'数据库记录')}${metric('涉及小组',data.groupsWithEvents+'组',s.groupCount+'组已配置')}${metric('文件记录',data.files,'项目知识库')}${metric('时间范围',data.events?'已形成':'无数据',range)}</div>
 <div class="grid cols-2 mt16"><section class="card"><h2>生成导出文件</h2><p>CSV 与 JSON 包含阶段、提示、版本和教师处理事件；小组仅使用去标识化编号。</p><div class="toolbar"><a class="btn primary" href="/api/export?format=csv">下载CSV</a><a class="btn green" href="/api/export?format=json">下载JSON</a></div><div class="note">不包含学生姓名、登录口令、上传文件原文或模型密钥。</div></section>
 <section class="card"><h2>最近服务器事件</h2><div style="max-height:360px;overflow:auto">${events.length?events.map(e=>`<div class="log-row">${esc(e.ts)} | ${e.group_no?`G${String(e.group_no).padStart(2,'0')}`:'CLASS'} | ${esc(e.event_type)} | ${esc(e.data)}</div>`).join(''):'<div class="empty">数据库中尚无课堂事件</div>'}</div></section></div>`));
}
async function renderTeacherGovernance(){
 const s=load(),runtime=await api('/api/runtime'),data=runtime.data,ai=runtime.ai,security=runtime.security;
 setRoot(shell('teacher','gov',head('运行与数据治理','此页显示服务器实时检测结果；固定产品边界单独标明为政策。',`<button class="btn ${s.aiOpen?'green':'danger'}" id="govAI">课堂AI${s.aiOpen?'开放':'暂停'}</button>`,'运行状态')+
 `<div class="grid cols-4">${metric('数据库',runtime.database.healthy?'正常':'异常',(runtime.database.sizeBytes/1024).toFixed(1)+' KB')}${metric('AI服务',ai.configured?'已配置':'未配置',ai.configured?ai.model:'使用教师支架')}${metric('课堂数据',data.events+'条事件',data.states+'个状态空间')}${metric('当前会话',data.sessions,'有效登录会话')}</div>
 <div class="grid cols-2 mt16"><section class="card"><h2>服务器配置</h2><div class="mini-stat"><span>运行环境</span><b>${esc(runtime.environment)}</b></div><div class="mini-stat"><span>安全Cookie</span><b>${security.secureCookie?'已启用':'未启用'}</b></div><div class="mini-stat"><span>会话有效期</span><b>${Math.round(security.sessionSeconds/60)}分钟</b></div><div class="mini-stat"><span>小组账户</span><b>${data.groups}组</b></div><div class="mini-stat"><span>上传文件</span><b>${data.files}个</b></div></section>
 <section class="card"><h2>模型调用</h2><div class="mini-stat"><span>调用总数</span><b>${ai.calls}</b></div><div class="mini-stat"><span>异常/降级</span><b>${ai.failedCalls}</b></div><div class="mini-stat"><span>当前模型</span><b>${ai.configured?esc(ai.model):'未连接外部模型'}</b></div><a class="btn mt12" href="audit.html">查看调用明细</a></section></div>
 <section class="card mt16"><h2>固定产品边界</h2><p class="muted">以下是系统设计政策，不是自动检测结论。</p><div class="grid cols-4"><div class="locked-rule"><span>持续录音录像</span>${badge('不提供','danger')}</div><div class="locked-rule"><span>自动情绪识别</span>${badge('不提供','danger')}</div><div class="locked-rule"><span>自动能力标签</span>${badge('不提供','danger')}</div><div class="locked-rule"><span>AI最终评分</span>${badge('不提供','danger')}</div></div></section>`));
 document.querySelector('#govAI').onclick=()=>{const x=load();x.aiOpen=!x.aiOpen;audit(x,'教师',x.aiOpen?'开放AI':'暂停AI','治理页');save(x);renderTeacherGovernance()};
}
function renderAudit(){const s=load(),calls=s.aiCalls||[];setRoot(shell('teacher','audit',head('审计与模型调用','记录教师关键控制、配置修改、导出、模型异常和模型标识。','','可追溯性')+`<div class="grid cols-2"><section class="card"><h2>关键操作审计</h2><div style="max-height:430px;overflow:auto">${s.audit.length?s.audit.map(a=>`<div class="log-row">${a.time} | ${a.actor} | ${a.action} | ${esc(a.detail)}</div>`).join(''):'<div class="empty">尚无关键操作记录</div>'}</div></section><section class="card"><h2>模型调用监控</h2><table class="table"><thead><tr><th>时间</th><th>组</th><th>层级</th><th>耗时</th><th>结果</th></tr></thead><tbody>${calls.length?calls.map(c=>`<tr><td>${esc(c.ts)}</td><td>${c.group_no}组</td><td>${esc(c.level)}</td><td>${c.latency_ms}ms</td><td>${badge(c.status,c.status==='returned'?'ok':'warn')}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">尚无模型调用记录</td></tr>'}</tbody></table><div class="note mt12">调用记录由服务器生成，不保存DeepSeek密钥，也不导出学生姓名。</div></section></div>`))}
async function renderAdminAccess(){
 const info=await api('/api/admin/access'),options=Array.from({length:info.groupCount},(_,i)=>`<option value="${i+1}">${i+1}组</option>`).join('');
 setRoot(shell('teacher','access',head('账号与访问管理','管理员可以重置教师账号、班级码和小组码；系统不提供任何旧密码或访问码的明文查看。','','管理员')+
 `<section class="card"><h2>管理员身份确认</h2><div class="form-grid"><div class="field"><label>当前教师密码</label><input id="adminCurrent" type="password" autocomplete="current-password"><small>每次重置都需要重新验证。</small></div><div class="mini-stat"><span>管理员账号</span><b>${esc(info.username)}</b></div><div class="mini-stat"><span>小组数量</span><b>${info.groupCount}组</b></div><div class="mini-stat"><span>恢复码</span><b>${info.recoveryConfigured?'已配置':'未配置'}</b></div></div></section>
 <div class="grid cols-2 mt16"><section class="card"><h2>教师账号</h2><div class="field"><label>教师账号</label><input id="adminUsername" value="${esc(info.username)}" autocomplete="username"></div><div class="field mt8"><label>新教师密码</label><input id="adminPassword" type="password" autocomplete="new-password"><small>不修改密码可留空；修改账号或密码后需重新登录。</small></div><button class="btn primary mt12" id="saveAdminAccount">保存教师账号</button></section>
 <section class="card"><h2>班级访问码</h2><div class="field"><label>新班级访问码</label><input id="newClassCode" type="password" autocomplete="new-password"><small>至少6位；保存后所有学生会话退出。</small></div><button class="btn primary mt12" id="resetClassCode">重置班级访问码</button></section>
 <section class="card"><h2>单个小组访问码</h2><div class="form-grid"><div class="field"><label>小组</label><select id="resetGroupNo">${options}</select></div><div class="field"><label>新小组访问码</label><input id="newGroupCode" type="password" autocomplete="new-password"></div></div><button class="btn primary mt12" id="resetGroupCode">重置所选小组</button></section>
 <section class="card"><h2>批量重置小组码</h2><div class="field"><label>新访问码前缀</label><input id="newGroupPrefix" type="password" autocomplete="new-password"><small>例如 TEAM 将生成 TEAM01、TEAM02……</small></div><button class="btn warn mt12" id="resetAllGroups">批量重置</button></section>
 <section class="card"><h2>管理员恢复码</h2><div class="field"><label>新恢复码</label><input id="newRecoveryCode" type="password" autocomplete="new-password"><small>至少16位，请离线保管；用于忘记教师密码时恢复。</small></div><button class="btn primary mt12" id="resetRecoveryCode">更新恢复码</button></section>
 <section class="card"><h2>安全说明</h2><div class="task-list"><div class="task"><b>旧凭据不可查看</b><small>教师密码、恢复码、班级码和小组码均只保存加盐哈希。</small></div><div class="task"><b>重置立即生效</b><small>相关教师或学生会话会失效，操作写入服务器审计事件。</small></div></div></section></div>`));
 const run=async(id,action,payload)=>{const button=document.querySelector(id);button.disabled=true;try{const result=await api('/api/admin/access',{method:'POST',body:JSON.stringify({action,currentPassword:document.querySelector('#adminCurrent').value,...payload()})});if(result.logoutRole==='teacher'){location.href='/?current';return}document.querySelector('#adminCurrent').value='';toast('访问凭据已更新')}catch(e){toast(e.message);button.disabled=false}};
 document.querySelector('#saveAdminAccount').onclick=()=>run('#saveAdminAccount','teacher',()=>({username:document.querySelector('#adminUsername').value,newPassword:document.querySelector('#adminPassword').value}));
 document.querySelector('#resetClassCode').onclick=()=>run('#resetClassCode','class_code',()=>({classCode:document.querySelector('#newClassCode').value}));
 document.querySelector('#resetGroupCode').onclick=()=>run('#resetGroupCode','group_code',()=>({groupNo:Number(document.querySelector('#resetGroupNo').value),groupCode:document.querySelector('#newGroupCode').value}));
 document.querySelector('#resetAllGroups').onclick=()=>run('#resetAllGroups','all_group_codes',()=>({groupPrefix:document.querySelector('#newGroupPrefix').value}));
 document.querySelector('#resetRecoveryCode').onclick=()=>run('#resetRecoveryCode','recovery_code',()=>({recoveryCode:document.querySelector('#newRecoveryCode').value}));
}
// ---------- Login entrance ----------
function renderAccessPortal(){
 _system={initialized:Boolean(_session.initialized),groupCount:Number(_session.groupCount||0)};
 const s=load();
 const frame=content=>`<div class="auth-shell"><aside class="auth-brand"><div class="auth-math" aria-hidden="true"><svg viewBox="0 0 720 900" preserveAspectRatio="none"><path d="M-40 610 C90 510 175 680 305 570 S525 390 760 455"/><path d="M-30 670 C115 575 210 735 350 620 S565 470 755 520" class="math-curve-secondary"/><line x1="82" y1="740" x2="650" y2="740"/><line x1="122" y1="790" x2="122" y2="260"/><circle cx="305" cy="570" r="7"/><circle cx="520" cy="456" r="7"/><text x="585" y="424">f(x)</text><text x="628" y="773">x</text><text x="91" y="286">y</text></svg></div><div class="brand"><span class="logo">Σ</span><span>数学项目协作智能体</span></div><div class="auth-copy"><div class="auth-kicker">MATHEMATICAL COLLABORATION</div><h1>让思考形成轨迹</h1><p>学生小组共同维护任务、模型和证据；教师独立管理项目、阶段、提示和评价。</p></div></aside><main class="auth-main"><div class="auth-card">${content}</div></main></div><div class="toast"></div>`;
if(!_system.initialized){
  setRoot(frame(`<h2>平台注册</h2><div class="form-grid"><div class="field"><label>教师注册码</label><input id="setupToken" type="password" autocomplete="one-time-code"></div><div class="field"><label>教师账号</label><input id="setupUser" autocomplete="username"></div><div class="field"><label>教师密码（至少12位）</label><input id="setupPass" type="password" autocomplete="new-password"></div><div class="field"><label>管理员恢复码（至少16位）</label><input id="setupRecovery" type="password" autocomplete="new-password" placeholder="用于找回教师密码，请离线保管"></div><div class="field"><label>班级访问码（至少6位）</label><input id="setupClassCode" type="password" autocomplete="new-password"></div><div class="field"><label>小组数量（1—20）</label><input id="setupGroupCount" type="number" min="1" max="20"></div><div class="field"><label>小组访问码前缀</label><input id="setupGroupPrefix" type="password" autocomplete="new-password" placeholder="前缀 + 两位组号，如 TEAM01"></div></div><div class="toolbar"><button class="btn primary" id="setupPlatform">完成注册</button></div>`));
  document.querySelector('#setupPlatform').onclick=async()=>{
   const button=document.querySelector('#setupPlatform');button.disabled=true;
   try{
    const result=await api('/api/setup',{method:'POST',body:JSON.stringify({setupToken:document.querySelector('#setupToken').value,username:document.querySelector('#setupUser').value,password:document.querySelector('#setupPass').value,recoveryCode:document.querySelector('#setupRecovery').value,classCode:document.querySelector('#setupClassCode').value,groupCount:Number(document.querySelector('#setupGroupCount').value),groupCodePrefix:document.querySelector('#setupGroupPrefix').value})});
    _system={initialized:true,groupCount:result.groupCount};_session={authenticated:false,initialized:true,groupCount:result.groupCount};toast('初始化完成，请登录教师端');setTimeout(renderAccessPortal,500);
   }catch(e){toast(e.message);button.disabled=false}
  };
  return;
 }
 if(_session.authenticated){
  const teacher=_session.role==='teacher';
  setRoot(frame(`<div class="eyebrow">${teacher?'教师端':'学生小组端'}</div><h2>当前已登录</h2><p class="muted">${teacher?'进入课堂总控管理项目与小组。':`进入${s.groupId}组共享工作区。`}</p><div class="toolbar"><a class="btn primary" href="${teacher?'teacher/dashboard.html':'student/dashboard.html'}">进入工作端</a><button class="btn" data-logout>退出登录</button></div>`));
  return;
 }
 setRoot(frame(`<div class="eyebrow">身份验证</div><h2>登录平台</h2><div class="auth-options"><section><h3>学生小组端</h3><div class="field"><label>班级访问码</label><input id="classCode" type="password" autocomplete="current-password"></div><div class="field mt8"><label>小组</label><select id="groupId">${Array.from({length:_system.groupCount},(_,i)=>`<option value="${i+1}">${i+1}组</option>`).join('')}</select></div><div class="field mt8"><label>小组访问码</label><input id="groupCode" type="password" autocomplete="current-password"></div><div class="toolbar"><button class="btn primary" id="studentLogin">登录学生小组端</button></div></section><section><h3>教师总控端</h3><div class="field"><label>教师账号</label><input id="teacherUser" autocomplete="username"></div><div class="field mt8"><label>密码</label><input id="teacherPass" type="password" autocomplete="current-password"></div><div class="toolbar"><button class="btn green" id="teacherLogin">登录教师总控端</button><button class="btn" id="showRecovery">忘记密码</button></div><div id="recoveryPanel" class="hide"><div class="divider"></div><h3>恢复教师密码</h3><div class="field"><label>教师账号</label><input id="recoverUser" autocomplete="username"></div><div class="field mt8"><label>管理员恢复码</label><input id="recoverCode" type="password" autocomplete="one-time-code"></div><div class="field mt8"><label>新教师密码（至少12位）</label><input id="recoverPassword" type="password" autocomplete="new-password"></div><button class="btn primary mt12" id="recoverTeacher">重置教师密码</button></div></section></div>`));
 document.querySelector('#studentLogin').onclick=async()=>{try{await api('/api/login',{method:'POST',body:JSON.stringify({role:'student',classCode:document.querySelector('#classCode').value,groupId:Number(document.querySelector('#groupId').value),groupCode:document.querySelector('#groupCode').value})});location.href='student/dashboard.html'}catch(e){toast(e.message)}};
 document.querySelector('#teacherLogin').onclick=async()=>{try{await api('/api/login',{method:'POST',body:JSON.stringify({role:'teacher',username:document.querySelector('#teacherUser').value,password:document.querySelector('#teacherPass').value})});location.href='teacher/dashboard.html'}catch(e){toast(e.message)}};
 document.querySelector('#showRecovery').onclick=()=>document.querySelector('#recoveryPanel').classList.toggle('hide');
 document.querySelector('#recoverTeacher').onclick=async()=>{const button=document.querySelector('#recoverTeacher');button.disabled=true;try{await api('/api/admin/recover',{method:'POST',body:JSON.stringify({username:document.querySelector('#recoverUser').value,recoveryCode:document.querySelector('#recoverCode').value,newPassword:document.querySelector('#recoverPassword').value})});document.querySelector('#teacherUser').value=document.querySelector('#recoverUser').value;document.querySelector('#recoveryPanel').classList.add('hide');toast('教师密码已重置，请使用新密码登录')}catch(e){toast(e.message);button.disabled=false}};
}
// Modal commit handlers use event delegation.
document.addEventListener('click',e=>{if(e.target?.matches('[data-logout]'))logout();if(e.target && e.target.id==='commitEvidence'){const x=load();const text=document.querySelector('#newEvidence').value.trim(),source=document.querySelector('#newSource').value;if(!text){toast('请填写证据内容');return}x.evidence.push({type:'新证据',text,source,verified:false});event(x,'evidence_add',text);save(x);document.querySelector('.modal-mask')?.remove();toast('证据已加入');setTimeout(renderEvidence,250)}if(e.target&&e.target.id==='saveTeacherNote'){const x=load(),gid=Number(new URLSearchParams(location.search).get('g')||x.groupId||1);const typ=document.querySelector('#noteType').value,txt=document.querySelector('#noteText').value;audit(x,'教师',typ,txt);const q=x.queue.find(q=>q.group===gid&&!q.resolved);if(q)q.resolved=true;event(x,'teacher_intervention',typ,`G${String(gid).padStart(2,'0')}`);save(x);document.querySelector('.modal-mask')?.remove();toast('教师处理已记录')}})
const pages={
 'student-dashboard':renderStudentDashboard,'student-stage1':()=>renderStage(1),'student-stage1-materials':renderStage1Materials,'student-stage1-roles':renderStage1Roles,
 'student-stage2':()=>renderStage(2),'student-stage2-understanding':renderStage2Understanding,'student-stage2-question-tree':renderQuestionTree,
 'student-stage3':()=>renderStage(3),'student-stage3-model':renderStage3Model,'student-stage3-graph':renderStage3Graph,'student-stage3-compare':renderCompare,'student-stage3-check':renderCheck,
 'student-stage4':()=>renderStage(4),'student-stage4-evidence':renderEvidence,'student-stage4-discussion':renderDiscussion,'student-stage4-versions':renderVersions,'student-stage4-tools':renderTools,
 'student-stage5':()=>renderStage(5),'student-stage5-product':renderProduct,'student-stage5-rehearsal':renderRehearsal,'student-stage5-reflection':renderReflection,
 'student-workspace':renderWorkspace,'student-help':renderHelp,'student-group':renderGroup,'student-history':renderHistory,'student-governance':renderStudentGovernance,
 'teacher-dashboard':renderTeacherDashboard,'teacher-project':renderProject,'teacher-template':renderTemplate,'teacher-knowledge':renderKnowledge,'teacher-scaffolds':renderScaffolds,'teacher-stages':renderStagesTeacher,'teacher-groups':renderGroups,'teacher-group-detail':renderGroupDetail,'teacher-queue':renderQueue,'teacher-common':renderCommon,'teacher-broadcast':renderBroadcast,'teacher-evaluation':renderEvaluation,'teacher-report':renderReport,'teacher-export':renderExport,'teacher-governance':renderTeacherGovernance,'teacher-audit':renderAudit,'teacher-access':renderAdminAccess,
 'portal':renderAccessPortal
};
async function boot(id){const fn=pages[id];if(!fn)throw new Error('Unknown page '+id);try{_session=await api('/api/session');if(id==='portal'){if(_session.authenticated){const data=await api('/api/state');_state=Object.assign(defaultState(),data.state||{})}await fn();return}const required=id.startsWith('student-')?'student':'teacher';if(!_session.authenticated||_session.role!==required){location.href='/?current';return}const group=_session.role==='teacher'?new URLSearchParams(location.search).get('g'):null;const data=await api('/api/state'+(group?`?group=${encodeURIComponent(group)}`:''));_state=Object.assign(defaultState(),data.state||{});const requested=id.match(/^student-stage([1-5])/);if(requested&&Number(requested[1])>_state.currentStage){location.href='dashboard.html';return}await fn();if(!Object.keys(data.state||{}).length)save(_state)}catch(e){setRoot(`<div class="hero"><div class="card"><h2>平台暂时不可用</h2><p>${esc(e.message)}</p><a class="btn" href="/?current">返回登录</a></div></div>`)}}
window.MPT={boot,load,save,reset,toast};
})();
